using System;using System.Collections.Generic;public class Solution{public bool ContainsNearbyAlmostDuplicate(int[]a,int k,int t){if(t<0)return false;long w=(long)t+1;long Id(long x)=>x>=0?x/w:(x+1)/w-1;var m=new Dictionary<long,long>();for(int i=0;i<a.Length;i++){long x=a[i],b=Id(x);if(m.ContainsKey(b)||m.ContainsKey(b-1)&&Math.Abs(x-m[b-1])<=t||m.ContainsKey(b+1)&&Math.Abs(x-m[b+1])<=t)return true;m[b]=x;if(i>=k)m.Remove(Id(a[i-k]));}return false;}}
